import 'dart:convert';
import 'dart:typed_data';

class AppAssetsB64 {
  const AppAssetsB64._();

  static const String _logoIconB64 = '';
  static const String _logoFullB64 = '';

  static Uint8List get logoIcon => base64Decode(_logoIconB64);
  static Uint8List get logoEmblem => base64Decode(_logoIconB64);
  static Uint8List get splashLogo => base64Decode(_logoIconB64);
  static Uint8List get logoFull => base64Decode(_logoFullB64);
}
